#ifndef PS5C_VK_NGG_GROUP_H
#define PS5C_VK_NGG_GROUP_H
#include <stdint.h>
#include <stdbool.h>

/* PRIMGEN enabled, ES is a vertex shader, no tessellation/GS, and culling
 * (not PRIMGEN_PASSTHRU). MAX_VERT_OUT belongs to GS and may remain stale. */
static inline bool vk_ngg_culling_triangle(uint32_t stages) {
    return (stages & 0x0200203fu) == 0x2010u;
}

/* Preserve the existing input partition. Both the compiled output limit
 * and every possible vertex generated by that partition must fit. Keep
 * full groups for missing/invalid metadata, and for more than two waves. */
static inline uint32_t vk_ngg_group_threads(uint32_t output,uint32_t maxvert,uint32_t inputs) {
    if(!output || output>256 || !maxvert || maxvert>256 || !inputs || inputs>64 ||
       (uint64_t)maxvert*inputs>256) return 256;
    uint32_t need=maxvert*inputs;
    if(need<output)need=output;
    return need<=64?64:need<=128?128:256;
}
#endif
